String rp(num n) { final s=n.round().toString(); final b=StringBuffer(); for(var i=0;i<s.length;i++){b.write(s[i]); if(i<s.length-1 && (s.length-i-1)%3==0)b.write('.');} return 'Rp $b'; }
double numv(String s){var v=s.trim().replaceAll('Rp','').replaceAll(' ','');if(v.isEmpty)return 0;if(v.contains(',')&&v.contains('.')){if(v.lastIndexOf(',')>v.lastIndexOf('.')){v=v.replaceAll('.','').replaceAll(',','.');}else{v=v.replaceAll(',','');}}else if(v.contains(',')){v=v.replaceAll(',','.');}else if(RegExp(r'^-?\d{1,3}(\.\d{3})+$').hasMatch(v)){v=v.replaceAll('.','');}return double.tryParse(v)??0;}
class RabItem { String name,unit; double volume,price; RabItem(this.name,this.unit,this.volume,this.price); double get total=>volume*price; Map<String,dynamic> toJson()=>{'name':name,'unit':unit,'volume':volume,'price':price}; factory RabItem.fromJson(Map<String,dynamic> j)=>RabItem('${j['name']??''}','${j['unit']??'unit'}',(j['volume'] as num? ?? 0).toDouble(),(j['price'] as num? ?? 0).toDouble()); }
