class _PreviewPainter extends CustomPainter {
 final String type,design; final int floors;
 _PreviewPainter({required this.type,required this.design,required this.floors});
 @override void paint(Canvas canvas,Size size){
  final sky=Paint()..color=const Color(0xFF193B70);final edge=Paint()..color=const Color(0xFF86B5FF)..style=PaintingStyle.stroke..strokeWidth=2;final face=Paint()..color=design.contains('Klasik')?const Color(0xFFE6D5B7):const Color(0xFFE9F1FC);final dark=Paint()..color=const Color(0xFF102A56);final glass=Paint()..color=const Color(0xFF3F8DDF);final ground=Paint()..color=const Color(0xFF5A7395);
  canvas.drawRect(Offset.zero&size,sky);canvas.drawLine(Offset(0,size.height-9),Offset(size.width,size.height-9),ground);
  if(type=='Jalan'){canvas.drawRect(Rect.fromLTWH(0,size.height*.42,size.width,size.height*.48),dark);final dash=Paint()..color=orange..strokeWidth=3;for(double x=8;x<size.width;x+=24){canvas.drawLine(Offset(x,size.height*.66),Offset(x+12,size.height*.66),dash);}return;}
  if(type=='Jembatan'){final y=size.height*.62;canvas.drawRect(Rect.fromLTWH(8,y,size.width-16,12),face);canvas.drawLine(Offset(8,y-10),Offset(size.width-8,y-10),edge);for(int i=0;i<8;i++){final x=12+i*(size.width-24)/7;canvas.drawLine(Offset(x,y-10),Offset(x,y),edge);}canvas.drawLine(Offset(18,y+12),Offset(18,size.height-10),edge);canvas.drawLine(Offset(size.width-18,y+12),Offset(size.width-18,size.height-10),edge);return;}
  final count=(type=='Rumah'||type=='Ruko'?floors:mathMin(floors,5));final w=size.width*.54;final h=size.height*.70;final x=(size.width-w)/2;final y=size.height-h-9;final rect=Rect.fromLTWH(x,y,w,h);canvas.drawRect(rect,face);canvas.drawRect(rect,edge);
  if(type=='Rumah'||type=='Ruko'||type=='Gudang'){final roof=Path()..moveTo(x-8,y+4)..lineTo(x+w/2,y-17)..lineTo(x+w+8,y+4)..close();canvas.drawPath(roof,Paint()..color=design.contains('Industrial')?orange:const Color(0xFFFFB74D));canvas.drawPath(roof,edge);}
